let vert = `#version 300 es
precision highp float;

in vec3 aPosition;
in vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

out vec2 vTexCoord;

void main() {
  // Apply the camera transform
  vec4 viewModelPosition =
      uModelViewMatrix *
      vec4(aPosition, 1.0);

  // Tell WebGL where the vertex goes
  gl_Position =
      uProjectionMatrix *
      viewModelPosition;  

  // Pass along data to the fragment shader
  vTexCoord = aTexCoord;
}`

let frag = `#version 300 es
precision highp float;

in vec2 vTexCoord;
out vec4 fragColor;

uniform sampler2D data;
uniform sampler2D spheremap;
uniform vec4 bbox;
uniform int numNodes;
uniform float k;
uniform float r;
uniform vec4 c;

float opSmoothUnion( float d1, float d2, float k )
{
	float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
	return mix( d2, d1, h ) - k*h*(1.0-h);
}

vec2 nodeCoord(int i) {
	float x = fract(float(i)/20.) + 1./40.;
	float y = floor(float(i)/20.)/20. + 1./40.;
	vec2 pos = texture(data, vec2(x, y)).xy;
	return mix(bbox.xy, bbox.zw, pos);
}

void main() {
	vec2 coord = mix(bbox.xy, bbox.zw, vTexCoord);

	float dist = 100000.;
	float avg = 0.;
	float total = 0.;
	for (int i = 0; i < 400; i++) {
		if (i >= numNodes) break;

		float dist2 = length(coord - nodeCoord(i)) - r;
		avg += pow(dist2, 2.);
		total += 1.;
		dist = opSmoothUnion(
			dist,
			dist2,
			k
		);
		// dist = min(dist, dist2);
	}
	avg /= total;
	// vec3 pos = vec3(coord, avg * 0.05);
	vec3 pos = vec3(coord, -40.*smoothstep(0., 2., pow(-dist, .1)));

	vec3 normal = -normalize(cross(dFdx(pos), dFdy(pos)));

	vec3 fromCam = normalize(pos - vec3(0., 0., -800.0));
	vec3 n = reflect(
		fromCam,
		normal
	);
	float phi = acos( n.y );
	float theta = 0.0;
	theta = acos(n.x / sin(phi));
	float sinTheta = n.z / sin(phi);
	if (sinTheta < 0.0) {
		// Turn it into -theta, but in the 0-2PI range
		theta = 2.0 * 3.14159 - theta;
	}
	theta = theta / (2.0 * 3.14159);
	phi = phi / 3.14159 ;
	vec2 angles = vec2( fract(theta + 0.25), 1.0 - phi );

	vec3 lightDir = normalize(vec3(-0.3, 0.9, 0.));
	float l = 0.15 * max(0., dot(lightDir, normal)) + 0.85;
	vec3 outColor = c.xyz * l + pow(texture(spheremap, angles).xyz, vec3(4.));
	// outColor = vec3(smoothstep(0., 2., pow(-dist, .15)));
	// outColor = normal;

	fragColor = vec4(outColor, 1.) * (1. - smoothstep(0., 0.01, dist));
}`

// === Tab: convexHull ===
const comparison = (a, b) => {
  return a.x == b.x ? a.y - b.y : a.x - b.x
}

const cross = (a, b, o) => {
  return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x)
}

function convexHull(points) {
  points.sort(comparison)
  const L = []
  for (let i = 0; i < points.length; i++) {
    while (
      L.length >= 2 &&
      cross(L[L.length - 2], L[L.length - 1], points[i]) <= 0
    ) {
      L.pop()
    }
    L.push(points[i])
  }
  const U = []
  for (let i = points.length - 1; i >= 0; i--) {
    while (
      U.length >= 2 &&
      cross(U[U.length - 2], U[U.length - 1], points[i]) <= 0
    ) {
      U.pop()
    }
    U.push(points[i])
  }
  L.pop()
  U.pop()
  return L.concat(U)
}

function computeCOM(hull) {
  // https://en.wikipedia.org/wiki/Centroid#Of_a_polygon
  let area = 0
  for (let i = 0; i < hull.length; i++) {
    const j = (i + 1) % hull.length
    area += hull[i].x * hull[j].y - hull[j].x * hull[i].y
  }
  area /= 2

  let x = 0
  let y = 0
  for (let i = 0; i < hull.length; i++) {
    const j = (i + 1) % hull.length
    x +=
      (hull[i].x + hull[j].x) * (hull[i].x * hull[j].y - hull[j].x * hull[i].y)
    y +=
      (hull[i].y + hull[j].y) * (hull[i].x * hull[j].y - hull[j].x * hull[i].y)
  }
  x /= 6 * area
  y /= 6 * area

  // @ts-ignore
  return createVector(x, y)
}

function ensureCCW(hull) {
  const com = computeCOM(hull)
  const angle0 =
    (Math.atan2(hull[0].y - com.y, hull[0].x - hull[0].x) + 2 * Math.PI) %
    (2 * Math.PI)
  const angle1 =
    (Math.atan2(hull[1].y - com.y, hull[1].x - hull[1].x) + 2 * Math.PI) %
    (2 * Math.PI)
  const diff = (angle1 - angle0 + 2 * Math.PI) % (2 * Math.PI)
  if (diff > Math.PI) {
    return hull
  } else {
    return [...hull].reverse()
  }
}

